import java.util.*;

public class ReportProcessor {
    public static void main(String[] args) {
        // Autoboxing: int → Integer when adding to List
        List<Integer> pageCounts = new ArrayList<>();
        pageCounts.add(42);  // compiler converts to Integer.valueOf(42)
        pageCounts.add(100);

        // Unboxing: Integer → int in arithmetic
        int firstPage = pageCounts.get(0);  // compiler calls .intValue()
        int total = firstPage + pageCounts.get(1);  // both unbox automatically

        // Mixed operations — boxing and unboxing
        Integer maxPages = 200;
        if (total > maxPages) {  // maxPages unboxes to int for comparison
            System.out.println("Report exceeds limit");
        }

        // The dangerous case: unboxing null throws NPE
        Map<String, Integer> reportStats = new HashMap<>();
        int errorCount = reportStats.get("errors");  // NPE if key missing!
    }
}

import java.util.*;

public class ReportStatistics {
    public static void main(String[] args) {
        Map<String, Integer> stats = new HashMap<>();
        stats.put("processed", 150);
        stats.put("pending", 45);

        // Safe: key exists, unboxing succeeds
        int processed = stats.get("processed");  // OK: 150

        // DANGER: key missing, returns null, unboxing throws NPE
        int errors = stats.get("errors");  // NullPointerException here!
        // Compiler generates: stats.get("errors").intValue()
        // Since get() returns null, this is null.intValue() → NPE

        // FIX 1: Use getOrDefault
        int errorsSafe = stats.getOrDefault("errors", 0);

        // FIX 2: Check for null before unboxing
        Integer errorsObj = stats.get("errors");
        int errorsChecked = (errorsObj != null) ? errorsObj : 0;

        // FIX 3: Use Optional wrapper
        int errorsOptional = Optional.ofNullable(stats.get("errors")).orElse(0);
    }
}

import java.util.*;
import java.util.stream.*;

public class PerformanceComparison {
    public static void main(String[] args) {
        int size = 1_000_000;

        // SLOW: ArrayList<Integer> causes boxing/unboxing
        List<Integer> boxedList = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            boxedList.add(i);  // autoboxing: creates Integer object
        }
        long sum1 = 0;
        for (Integer num : boxedList) {
            sum1 += num;  // unboxing on every iteration
        }

        // FAST: primitive array — no boxing
        int[] primitiveArray = new int[size];
        for (int i = 0; i < size; i++) {
            primitiveArray[i] = i;  // direct assignment
        }
        long sum2 = 0;
        for (int num : primitiveArray) {
            sum2 += num;  // direct arithmetic
        }

        // FAST: IntStream avoids boxing in functional style
        long sum3 = IntStream.range(0, size).asLongStream().sum();
    }
}

public class IntegerCacheDemo {
    public static void main(String[] args) {
        // Cached range: -128 to 127 — same object returned
        Integer a = 100;
        Integer b = 100;
        System.out.println(a == b);  // true — both reference cached object
        System.out.println(a.equals(b));  // true — value comparison

        // Outside cache range — new objects created
        Integer x = 200;
        Integer y = 200;
        System.out.println(x == y);  // false — different objects!
        System.out.println(x.equals(y));  // true — value comparison

        // Real-world bug: comparing user IDs or counts
        Integer userId1 = getUserIdFromDatabase();  // returns 50
        Integer userId2 = getUserIdFromCache();     // returns 50
        if (userId1 == userId2) {  // works by accident (cached)
            System.out.println("Same user");
        }

        Integer reportCount1 = getReportCount();  // returns 500
        Integer reportCount2 = getReportCount();  // returns 500
        if (reportCount1 == reportCount2) {  // FAILS (not cached)
            System.out.println("This never prints!");
        }
    }

    static Integer getUserIdFromDatabase() { return 50; }
    static Integer getUserIdFromCache() { return 50; }
    static Integer getReportCount() { return 500; }
}
